package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

type jsonTheme struct {
	colors      map[string]string
	colorsDark  map[string]string
	colorsLight map[string]string
	sizes       map[string]float32
	fonts       map[string]string
	icons       map[string]string

	base fyne.Theme
}

type jsonThemeData struct {
	Colors      map[string]string  `json:"Colors"`
	ColorsDark  map[string]string  `json:"Colors-dark"`
	ColorsLight map[string]string  `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string  `json:"Fonts"`
	Icons       map[string]string  `json:"Icons"`
}

// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var data jsonThemeData
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&data); err != nil {
		return DefaultTheme(), err
	}

	theme := &jsonTheme{
		colors:      data.Colors,
		colorsDark:  data.ColorsDark,
		colorsLight: data.ColorsLight,
		sizes:       data.Sizes,
		fonts:       data.Fonts,
		icons:       data.Icons,
		base:        DefaultTheme(),
	}

	return theme, nil
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	colorName := string(name)

	// Check variant-specific colors first
	var hexStr string
	if variant == fyne.ThemeVariantDark && t.colorsDark != nil {
		if hex, ok := t.colorsDark[colorName]; ok {
			hexStr = hex
		}
	} else if variant == fyne.ThemeVariantLight && t.colorsLight != nil {
		if hex, ok := t.colorsLight[colorName]; ok {
			hexStr = hex
		}
	}

	// Fall back to generic colors
	if hexStr == "" && t.colors != nil {
		if hex, ok := t.colors[colorName]; ok {
			hexStr = hex
		}
	}

	// Parse hex color if found
	if hexStr != "" {
		if c, err := parseHexColor(hexStr); err == nil {
			return c
		}
	}

	// Fall back to base theme
	return t.base.Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	if t.fonts == nil {
		return t.base.Font(style)
	}

	var fontName string
	if style.Bold && style.Italic {
		fontName = "boldItalic"
	} else if style.Bold {
		fontName = "bold"
	} else if style.Italic {
		fontName = "italic"
	} else if style.Monospace {
		fontName = "monospace"
	} else {
		fontName = "regular"
	}

	if uriStr, ok := t.fonts[fontName]; ok {
		if uri, err := storage.ParseURI(uriStr); err == nil {
			// In a real implementation, you'd load the resource from the URI
			// For now, we'll fall back to the base theme
			_ = uri
		}
	}

	return t.base.Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if t.icons != nil {
		if uriStr, ok := t.icons[string(name)]; ok {
			if uri, err := storage.ParseURI(uriStr); err == nil {
				// In a real implementation, you'd load the resource from the URI
				// For now, we'll fall back to the base theme
				_ = uri
			}
		}
	}

	return t.base.Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if t.sizes != nil {
		if size, ok := t.sizes[string(name)]; ok {
			return size
		}
	}

	return t.base.Size(name)
}

// parseHexColor parses a hex color string and returns a color.Color.
// Supports formats: #RGB, #RGBA, #RRGGBB, #RRGGBBAA (with or without # prefix)
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8 = 0, 0, 0, 0xff

	switch len(hex) {
	case 3: // RGB
		if _, err := fmt.Sscanf(hex, "%1x%1x%1x", &r, &g, &b); err != nil {
			return color.Transparent, err
		}
		// Expand 4-bit to 8-bit: 0xA -> 0xAA
		r = r<<4 | r
		g = g<<4 | g
		b = b<<4 | b

	case 4: // RGBA
		if _, err := fmt.Sscanf(hex, "%1x%1x%1x%1x", &r, &g, &b, &a); err != nil {
			return color.Transparent, err
		}
		// Expand 4-bit to 8-bit
		r = r<<4 | r
		g = g<<4 | g
		b = b<<4 | b
		a = a<<4 | a

	case 6: // RRGGBB
		if _, err := fmt.Sscanf(hex, "%02x%02x%02x", &r, &g, &b); err != nil {
			return color.Transparent, err
		}

	case 8: // RRGGBBAA
		if _, err := fmt.Sscanf(hex, "%02x%02x%02x%02x", &r, &g, &b, &a); err != nil {
			return color.Transparent, err
		}

	default:
		return color.Transparent, fmt.Errorf("invalid hex color format: %s", hex)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

