func (s *stringFormat) getValue(item DataItem) (interface{}, error) {
	switch v := item.(type) {
	case String:
		return v.Get()
	case Bool:
		return v.Get()
	case Float:
		return v.Get()
	case Int:
		return v.Get()
	case Untyped:
		return v.Get()
	default:
		return nil, fmt.Errorf("unsupported binding type: %T", item)
	}
}

