// NewAllStrings creates a validator that passes a list of sub-validators and requires all of them to pass.
// The validator will return nil if all sub-validators return nil, otherwise returns the first error encountered.
//
// Since: 2.5
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(text); err != nil {
				return err
			}
		}
		return nil
	}
}

