package desktop

import "fyne.io/fyne/v2"

// App defines the desktop-specific extensions to the application interface.
// This interface adds system tray functionality that is available on desktop platforms.
//
// Since: 2.5
type App interface {
	// SetSystemTrayMenu sets the menu for the system tray icon.
	// This allows the application to display a custom menu when the user interacts with the tray icon.
	SetSystemTrayMenu(menu *fyne.Menu)

	// SetSystemTrayIcon sets the icon to be displayed in the system tray.
	// The icon should be a square image that will be scaled appropriately for the platform.
	SetSystemTrayIcon(icon fyne.Resource)
}

